  c = mix(c, vec3(0.570, 0.385, 0.255), smoothstep(396.0, 404.0, h));
  c = mix(c, vec3(0.440, 0.220, 0.140), smoothstep(440.0, 450.0, h));
  c = mix(c, vec3(0.345, 0.360, 0.265), smoothstep(535.0, 546.0, h));
